# >>> CHOICES
if [[ -n "$ARGC_COMPLETIONS_ROOT" && -f "$ARGC_COMPLETIONS_ROOT/utils/_argc_utils.sh" ]]; then
    . "$ARGC_COMPLETIONS_ROOT/utils/_argc_utils.sh"
fi

_choice_archive_sort_keys() {
    printf '%s\t%s\n' \
        timestamp 'archive timestamp' \
        archive 'archive name' \
        name 'item name' \
        id 'archive id'
}

_choice_command() {
    if _argc_util_has_path_prefix; then
        _argc_util_comp_path
        return 0
    fi
    _argc_util_comp_command
}

_choice_command_args() {
    if [[ "${#argc__positionals[@]}" -lt 2 ]]; then
        _choice_command
    else
        _argc_util_comp_subcommand 1
    fi
}

_choice_compression() {
    printf '%s\t%s\n' \
        none 'do not compress' \
        lz4 'very fast, very low compression (default)' \
        zstd 'zstandard, wide-range compression' \
        zlib 'zlib (gz), medium speed and compression' \
        lzma 'lzma (xz), low speed, high compression'
}

_choice_diff_sort_fields() {
    printf '%s\t%s\n' \
        path 'item path' \
        size_added 'total bytes added for the item content' \
        size_removed 'total bytes removed for the item content' \
        size_diff 'size_added - size_removed' \
        size 'item size as stored in ARCHIVE2' \
        user 'user name from ARCHIVE2' \
        group 'group name from ARCHIVE2' \
        uid 'user id from ARCHIVE2' \
        gid 'group id from ARCHIVE2' \
        ctime 'ctime from ARCHIVE2' \
        mtime 'mtime from ARCHIVE2' \
        ctime_diff 'ctime difference (archive2 - archive1)' \
        mtime_diff 'mtime difference (archive2 - archive1)'
}

_choice_status_filter() {
    printf '%s\t%s\n' \
        A 'regular file, added' \
        M 'regular file, modified' \
        U 'regular file, unchanged' \
        C 'regular file, changed while it was backed up' \
        E 'regular file, error while reading it'
}
# <<< CHOICES

command eval "$(argc --argc-eval "$0" "$@")"
